static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float norm_in[NN_INPUT_DIM];
    for (int i = 0; i < NN_INPUT_DIM; i++) {
        norm_in[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    float h1[128], h2[128];
    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < NN_INPUT_DIM; j++) sum += W0[i * NN_INPUT_DIM + j] * norm_in[j];
        h1[i] = relu(sum);
    }

    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) sum += W1[i * 128 + j] * h1[j];
        h2[i] = relu(sum);
    }

    float out = b2[0];
    for (int i = 0; i < 128; i++) out += W2[i] * h2[i];
    if (out > 80.0f) out = 80.0f;
    if (out < 0.0f)  out = 0.0f;
    return out;
}

/* Simulador de Planta Fisica Grey-Box v5 no STM32 SIL (RK4 100 Hz) */
static float sil_th_rad = 0.0f;
static float sil_v_rad  = 0.0f;
static float sil_a_pct  = 0.0f;
static float sil_y_hist[1] = {0.0f};

static float simulate_narx(float u_cmd) {
    const float dt = 0.01f;
    float th = sil_th_rad;
    float v  = sil_v_rad;
    float a  = sil_a_pct;
    for (int step = 0; step < 4; step++) {
        float z = a - GB_U0;
        float thrust = (z > 0.0f) ? z * z : 0.0f;
        float fric = -GB_FC * tanhf(50.0f * v);
        float aero = -GB_C_AERO * v * fabsf(v);
        float acc = GB_C1 * sinf(th) + GB_C2 * v + aero + fric + GB_C3 * thrust;
        float adot = (u_cmd - a) / GB_TAU_M;
        th += (dt / 4.0f) * v;
        v  += (dt / 4.0f) * acc;
        a  += (dt / 4.0f) * adot;
    }
    sil_th_rad = th;
    sil_v_rad  = v;
    sil_a_pct  = a;
    float ang_deg = th * 180.0f / (float)M_PI;
    sil_y_hist[0] = ang_deg;
    return ang_deg;
}

#endif // ANN_WEIGHTS_H
